// A micro-benchmark that respects the three big traps:
// warmup (JIT), outlier noise (median), and dead-code elimination (consume result).

function bench(fn, { samples = 50, warmup = 3 } = {}) {
  for (let i = 0; i < warmup; i++) fn()       // compile before measuring
  const times = []
  const sink = []                              // keep results observable:
  for (let i = 0; i < samples; i++) {          // an unused result lets the
    const t0 = performance.now()               // optimizer delete the work
    sink.push(fn() ?? 0)
    times.push(performance.now() - t0)
  }
  if (sink.length !== samples) throw new Error("harness error")
  times.sort((a, b) => a - b)
  return {
    median: times[Math.floor(samples / 2)],
    p90: times[Math.floor(samples * 0.9)],
    samples
  }
}

const a = bench(() => JSON.parse(JSON.stringify({ x: 1, y: 2 })))
const b = bench(() => ({ ...{ x: 1, y: 2 } }))
console.log("clone vs spread (ms):", a, b)
